 public static void main(String[] args) throws InterruptedException {
    nonUniformDispatch();
    uniformDispatch();
}

static void nonUniformDispatch() throws InterruptedException {
    Random rand = new Random();
    double it = 1_000;
    int goal = 30;
    int dispatches = 0;
    for (int i = 0; i < it; i++) {
        if (goal > rand.nextInt(100)) {
            dispatches++;
            System.out.print("X");
        } else {
            System.out.print("_");
        }
    }
    System.out.println("\n\ndispatches = " + dispatches);
}

static void uniformDispatch() throws InterruptedException {
    int totalUnits = 3;
    Random rand = new Random();
    double it = 1_000;
    int dispatches = 0;
    int totalSlots = 10;
    int unitsRemaining = totalUnits;
    int slotsRemaining = totalSlots;
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < it; i++) {
//            System.out.println("slotsRemaining = " + slotsRemaining + ", unitsRemaining = " + unitsRemaining);
        if (slotsRemaining <= unitsRemaining) {
            dispatches++;
            unitsRemaining--;
            sb.append("X");
        } else if (unitsRemaining > 0) {
            int x = (unitsRemaining * 100) / slotsRemaining;
            if (x > rand.nextInt(100)) {
                dispatches++;
                unitsRemaining--;
                sb.append("X");
//                    System.out.println("x = " + x + ", hit");
            } else {
                sb.append("_");
//                    System.out.println("x = " + x + ", miss");
            }
        } else {
            sb.append("_");
//                System.out.println("miss");
        }
        slotsRemaining--;
        if (slotsRemaining == 0) {
            slotsRemaining = totalSlots;
            unitsRemaining = totalUnits;
        }
    }
    System.out.println(sb.toString());
    System.out.println("\n\ndispatches = " + dispatches);
    TimeUnit.SECONDS.sleep(10);
}


Answer: Let $C \subset \mathbb R^n$ be convex. It is clear that you can write
$$
\bar C = \bigcap_{i \in I} H_i
$$
for some index set $I$ and some closed half-spaces $H_i$.
Now, for every $x \in \mathrm{bd}(C) \setminus C$, there is a closed half-space $\tilde H_x$ with $C \subset \tilde H_x$ and $x \in \mathrm{bd}(\tilde H_x)$. Then, $H_x := \tilde H_x \setminus \{x\}$ is a half-space and we have
$$
C = \bigcap_{i \in I} H_i \cap \bigcap_{x \in \mathrm{bd}(C)\setminus C} H_x.$$ 
